/* Docker & Kubernetes Quest service worker.
 * Generated by scripts/generate-sw.mjs from sw/sw-template.js after `next build` — do not edit public/sw.js by hand.
 */
/* global self, caches */

// Placeholders are filled in by scripts/generate-sw.mjs; the template stays valid JS for linting.
const VERSION = "__BUILD_ID__";
const PRECACHE_PAGES = /* __PRECACHE_PAGES__ */ [];
const PRECACHE_ASSETS = /* __PRECACHE_ASSETS__ */ [];

const PREFIX = "dkq-";
const PRECACHE = `${PREFIX}precache-${VERSION}`;
const RUNTIME = `${PREFIX}runtime-${VERSION}`;
const RUNTIME_MAX_ENTRIES = 60;
const OFFLINE_URL = "/offline";
const NAV_TIMEOUT_MS = 4000;
// Pages the app cannot work without offline; install fails (and is retried on the next visit) if these do not cache.
const REQUIRED_PAGES = ["/", OFFLINE_URL];

async function cacheUrls(cache, urls, required) {
  const failed = [];
  await Promise.all(
    urls.map(async (url) => {
      for (let attempt = 0; attempt < 2; attempt++) {
        try {
          const res = await fetch(url, { cache: "reload", credentials: "same-origin" });
          if (res.ok && !res.redirected) {
            await cache.put(url, res);
            return;
          }
        } catch {
          // retry once, then record the failure
        }
      }
      failed.push(url);
    }),
  );
  if (required && failed.length) throw new Error(`Precache failed for: ${failed.join(", ")}`);
  return failed;
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      await cacheUrls(cache, REQUIRED_PAGES, true);
      await cacheUrls(cache, PRECACHE_ASSETS, true);
      const optional = PRECACHE_PAGES.filter((p) => !REQUIRED_PAGES.includes(p));
      const failed = await cacheUrls(cache, optional, false);
      if (failed.length) console.warn(`[sw] ${failed.length} page(s) not precached; they will cache on first visit.`, failed);
      // No skipWaiting here: an update waits until the learner chooses to refresh.
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keep = new Set([PRECACHE, RUNTIME]);
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n.startsWith(PREFIX) && !keep.has(n)).map((n) => caches.delete(n)));
      if (self.registration.navigationPreload) await self.registration.navigationPreload.enable();
      await self.clients.claim();
    })(),
  );
});

self.addEventListener("message", (event) => {
  const data = event.data || {};
  if (data.type === "SKIP_WAITING") self.skipWaiting();
  if (data.type === "GET_VERSION") event.source?.postMessage({ type: "VERSION", version: VERSION, pages: PRECACHE_PAGES.length });
});

// Tell open pages a network request failed; navigator.onLine alone misses "connected but no internet".
async function notifyNetworkFailed() {
  const windows = await self.clients.matchAll({ type: "window" });
  windows.forEach((c) => c.postMessage({ type: "NETWORK_FAILED" }));
}

async function trimRuntime() {
  const cache = await caches.open(RUNTIME);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - RUNTIME_MAX_ENTRIES; i++) await cache.delete(keys[i]);
}

async function matchPage(url) {
  // Cached pages are keyed by pathname; ignore query strings (e.g. ?tab=).
  return caches.match(url.pathname, { ignoreSearch: true });
}

function withTimeout(promise, ms) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("timeout")), ms);
    promise.then(
      (v) => (clearTimeout(timer), resolve(v)),
      (e) => (clearTimeout(timer), reject(e)),
    );
  });
}

async function handleNavigation(event, url) {
  const network = (async () => {
    const preloaded = await event.preloadResponse;
    return preloaded || fetch(event.request);
  })();
  try {
    const res = await withTimeout(network, NAV_TIMEOUT_MS);
    if (res.ok && (res.headers.get("content-type") || "").includes("text/html")) {
      const copy = res.clone();
      event.waitUntil(
        (async () => {
          // Refresh precached pages in place; other pages go to the bounded runtime cache.
          const name = PRECACHE_PAGES.includes(url.pathname) ? PRECACHE : RUNTIME;
          await (await caches.open(name)).put(url.pathname, copy);
          if (name === RUNTIME) await trimRuntime();
        })(),
      );
    }
    return res;
  } catch {
    // Only a real network error means offline; a timeout on a slow network does not.
    event.waitUntil(network.then(() => {}, () => notifyNetworkFailed()));
    const cached = await matchPage(url);
    if (cached) {
      // Keep the slow network response for the cache if it eventually arrives.
      event.waitUntil(network.then((r) => r.ok && caches.open(RUNTIME).then((c) => c.put(url.pathname, r))).catch(() => {}));
      return cached;
    }
    return (await caches.match(OFFLINE_URL)) || new Response("You are offline.", { status: 503, headers: { "content-type": "text/plain" } });
  }
}

async function cacheFirst(request) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const res = await fetch(request);
  if (res.ok) {
    const cache = await caches.open(RUNTIME);
    await cache.put(request, res.clone());
    trimRuntime();
  }
  return res;
}

async function staleWhileRevalidate(event) {
  const cached = await caches.match(event.request);
  const network = fetch(event.request)
    .then(async (res) => {
      if (res.ok) await (await caches.open(RUNTIME)).put(event.request, res.clone());
      return res;
    })
    .catch(() => {
      event.waitUntil(notifyNetworkFailed());
      return undefined;
    });
  if (cached) {
    event.waitUntil(network);
    return cached;
  }
  return (await network) || new Response("", { status: 504, statusText: "Offline" });
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname === "/sw.js") return;

  // React Server Component payloads (soft navigations / prefetches): network only, never cached.
  // When the network fails, answer 503: the router treats a non-OK response as "do a full navigation",
  // which the navigation handler below serves from the page cache. (A thrown fetch would do the same
  // but logs a console error.)
  if (request.headers.get("RSC") === "1" || url.searchParams.has("_rsc")) {
    event.respondWith(
      fetch(request).catch(() => {
        event.waitUntil(notifyNetworkFailed());
        return new Response(null, { status: 503, statusText: "Offline" });
      }),
    );
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(event, url));
    return;
  }
  if (url.pathname.startsWith("/_next/static/")) {
    event.respondWith(cacheFirst(request));
    return;
  }
  if (url.pathname.startsWith("/_next/")) return;
  event.respondWith(staleWhileRevalidate(event));
});
